    "exam_set": "multiple_choice",
    "question_text": "In public health calculations, if the annual target infant cohort is 1,000 infants and the Pentavalent vaccine requires 3 administrations per infant with a wastage multiplier of 1.1, how many total units of vaccine must be procured for the year?",
